import sys, json, urllib.request, hashlib

d = json.load(sys.stdin)
videos = d.get('videos', [])

# Group by size to find potential duplicates
size_groups = {}
for v in videos:
    url = v.get('video_url', '')
    if url:
        try:
            req = urllib.request.Request(url, method='HEAD')
            resp = urllib.request.urlopen(req, timeout=10)
            size = resp.headers.get('content-length', '0')
            etag = resp.headers.get('etag', 'none')
            size_groups.setdefault(size, []).append({
                'id': v.get('id','?')[:12],
                'title': v.get('title','?')[:40],
                'url': url.split('/')[-1][:30],
                'etag': etag
            })
        except:
            pass

print('=== Videos grouped by file size ===')
for size, vids in size_groups.items():
    if len(vids) > 1:
        print(f'  Size {size} bytes ({len(vids)} videos):')
        for v in vids:
            print(f'    {v[\"id\"]}: {v[\"title\"]} | file={v[\"url\"]} | etag={v[\"etag\"]}')
        # Check if same URL or different URL
        urls = [v['url'] for v in vids]
        if len(set(urls)) == 1:
            print(f'    → SAME FILE (true duplicate)')
        else:
            print(f'    → DIFFERENT FILES (same size, different content)')
    else:
        print(f'  Size {size} bytes (1 video): {vids[0][\"id\"]} - {vids[0][\"title\"]}')
" 2>/dev/null && echo "" && echo "=== POSTER URLS: Verify each is unique ===" && curl -sS "https://api.ivxholding.com/api/ivx/videos/feed?limit=24" 2>/dev/null | python3 -c "
import sys, json, urllib.request

d = json.load(sys.stdin)
videos = d.get('videos', [])

poster_groups = {}
for v in videos:
    poster = v.get('poster_url', '') or v.get('thumbnail_url', '')
    if poster:
        poster_groups.setdefault(poster, []).append(v.get('title','?')[:40])

print('=== Poster URL uniqueness ===')
dupes = 0
for url, titles in poster_groups.items():
    if len(titles) > 1:
        print(f'  DUPLICATE: {url[-30:]} → {titles}')
        dupes += 1
    else:
        print(f'  UNIQUE: {url[-30:]} → {titles[0]}')
print(f'\\nDuplicate posters: {dupes}')
" 2>/dev/null

